script:
html { scroll-behavior: smooth; }
::selection { background: #E4572E; color: #F5EEDF; }

/* reveal on scroll: armed by groove_motion only when motion is allowed */
html.gr-js .gr-rise { opacity: 0; transform: translateY(24px); }
html.gr-js .gr-rise.gr-in {
  opacity: 1; transform: none;
  transition: opacity 0.85s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}
html.gr-js .gr-d2.gr-in { transition-delay: 0.1s; }
html.gr-js .gr-d3.gr-in { transition-delay: 0.2s; }
html.gr-js .gr-d4.gr-in { transition-delay: 0.3s; }

/* ---- the record: grooves in CSS, spin driven by --spin from scroll ---- */
.gr-disc {
  background:
    radial-gradient(circle at 38% 32%, rgba(255, 246, 225, 0.05), transparent 60%),
    repeating-radial-gradient(circle at 50% 50%, #171208 0px, #171208 2px,
      #292013 2.6px, #171208 3.4px);
  box-shadow: 0 30px 80px rgba(25, 19, 9, 0.35), inset 0 0 0 2px #0D0A04;
  transform: rotate(var(--spin, 0deg));
}
.gr-sheen {
  background: conic-gradient(from 215deg,
    rgba(255, 246, 225, 0.14), transparent 16%,
    transparent 44%, rgba(255, 246, 225, 0.09) 52%, transparent 60%,
    transparent 86%, rgba(255, 246, 225, 0.14));
  pointer-events: none;
}
.gr-arm {
  transform: rotate(calc(14deg + var(--armp, 0) * 17deg));
  transform-origin: 50% -26px;
}

/* now-playing pill: pointless without the scroll driver */
.gr-pill { display: none; }
html.gr-js .gr-pill { display: flex; }

/* sleeves eject their record on hover */
.gr-minidisc {
  background:
    repeating-radial-gradient(circle at 50% 50%, #171208 0px, #171208 2px,
      #292013 2.6px, #171208 3.4px);
  box-shadow: 0 0 0 2px rgba(245, 238, 223, 0.55),
    0 10px 30px rgba(25, 19, 9, 0.35);
  transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
.gr-sleeve { z-index: 1; }
.gr-sleeve:hover { z-index: 20; }
.gr-sleeve:hover .gr-minidisc { transform: translateX(36%) rotate(80deg); }

/* crate flip */
.gr-crate-sleeve {
  transform: perspective(1100px) rotateY(-8deg);
  transition: transform 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.55s ease;
}
.gr-crate-sleeve:hover {
  transform: perspective(1100px) rotateY(0deg) translateY(-8px);
  box-shadow: 8px 12px 0 rgba(25, 19, 9, 0.25);
}
.gr-snap { scroll-snap-type: x mandatory; scrollbar-width: none; }
.gr-snap::-webkit-scrollbar { display: none; }
.gr-snap > * { scroll-snap-align: start; }

/* micro-interactions */
.gr-btn {
  box-shadow: 3px 3px 0 #191309;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.gr-btn:hover { box-shadow: 1px 1px 0 #191309; transform: translate(2px, 2px); }
.gr-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 2px;
  transition: background-size 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.gr-ul:hover { background-size: 100% 2px; }
.gr-track { transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1); }
.gr-track:hover { transform: translateX(8px); }
.gr-zoom img { transition: transform 1.2s cubic-bezier(0.22, 1, 0.36, 1); }
.gr-zoom:hover img { transform: scale(1.04); }

@media (prefers-reduced-motion: no-preference) {
  .gr-pulse { animation: gr-pulse 1.4s ease-in-out infinite; }
  @keyframes gr-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
  .gr-marquee-track { animation: gr-marquee 42s linear infinite; }
  .gr-marquee:hover .gr-marquee-track { animation-play-state: paused; }
  @keyframes gr-marquee { to { transform: translateX(-50%); } }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .gr-disc { transform: none; }
  .gr-arm { transform: rotate(20deg); }
}
